import{_ as l,a0 as d,w as o,s as c,ao as p,I as t,x as s,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Java 中的數據流和函數式編程 | LCTT x X-CMD","titleTemplate":false,"description":"Java 中的數據流和函數式編程 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Java 中的數據流和函數式編程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Java 中的數據流和函數式編程 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200102 Data streaming and functional programming in Java","title":"Java 中的數據流和函數式編程","tag":"202002","desc":""},"relativePath":"202002/20200102 Data streaming and functional programming in Java.md","filePath":"[post].md"}'),r={name:"202002/20200102 Data streaming and functional programming in Java.md"};function g(u,a,h,b,k,m){const e=d("Link");return o(),c("div",null,[a[18]||(a[18]=p(`<h1 id="java-中的數據流和函數式編程" tabindex="-1">Java 中的數據流和函數式編程 <a class="header-anchor" href="#java-中的數據流和函數式編程" aria-label="Permalink to “Java 中的數據流和函數式編程”">​</a></h1><blockquote><p>學習如何使用 Java 8 中的流 API 和函數式編程結構。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/06/002505flazlb4cg4aavvb4.jpg" alt=""></p><p>當 Java SE 8（又名核心 Java 8）在 2014 年被推出時，它引入了一些更改，從根本上影響了用它進行的編程。這些更改中有兩個緊密相連的部分：流 API 和函數式編程構造。本文使用代碼示例，從基礎到高級特性，介紹每個部分並説明它們之間的相互作用。</p><h3 id="基礎特性" tabindex="-1">基礎特性 <a class="header-anchor" href="#基礎特性" aria-label="Permalink to “基礎特性”">​</a></h3><p>流 API 是在數據序列中迭代元素的簡潔而高級的方法。包 <code>java.util.stream</code> 和 <code>java.util.function</code> 包含了用於流 API 和相關函數式編程構造的新庫。當然，代碼示例勝過千言萬語。</p><p>下面的代碼段用大約 2,000 個隨機整數值填充了一個 <code>List</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Random rand = new Random2();</span></span>
<span class="line"><span>List&lt;Integer&gt; list = new ArrayList&lt;Integer&gt;();           // 空 list</span></span>
<span class="line"><span>for (int i = 0; i &lt; 2048; i++) list.add(rand.nextInt()); // 填充它</span></span></code></pre></div><p>另外用一個 <code>for</code> 循環可用於遍歷填充列表，以將偶數值收集到另一個列表中。</p><p>流 API 提供了一種更簡潔的方法來執行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>List &lt;Integer&gt; evens = list</span></span>
<span class="line"><span>    .stream()                      // 流化 list</span></span>
<span class="line"><span>    .filter(n -&gt; (n &amp; 0x1) == 0)   // 過濾出奇數值</span></span>
<span class="line"><span>    .collect(Collectors.toList()); // 收集偶數值</span></span></code></pre></div><p>這個例子有三個來自流 API 的函數：</p><ul><li><code>stream</code> 函數可以將<strong>集合</strong>轉換為流，而流是一個每次可訪問一個值的傳送帶。流化是惰性的（因此也是高效的），因為值是根據需要產生的，而不是一次性產生的。</li><li><code>filter</code> 函數確定哪些流的值（如果有的話）通過了處理管道中的下一個階段，即 <code>collect</code> 階段。<code>filter</code> 函數是 <ruby>高階的<rt>higher-order</rt></ruby>，因為它的參數是一個函數 —— 在這個例子中是一個 lambda 表達式，它是一個未命名的函數，並且是 Java 新的函數式編程結構的核心。</li></ul><p>lambda 語法與傳統的 Java 完全不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n -&gt; (n &amp; 0x1) == 0</span></span></code></pre></div><p>箭頭（一個減號後面緊跟着一個大於號）將左邊的參數列表與右邊的函數體分隔開。參數 <code>n</code> 雖未明確類型，但也可以明確。在任何情況下，編譯器都會發現 <code>n</code> 是個 <code>Integer</code>。如果有多個參數，這些參數將被括在括號中，並用逗號分隔。</p><p>在本例中，函數體檢查一個整數的最低位（最右）是否為零，這用來表示偶數。過濾器應返回一個布爾值。儘管可以，但該函數的主體中沒有顯式的 <code>return</code>。如果主體沒有顯式的 <code>return</code>，則主體的最後一個表達式即是返回值。在這個例子中，主體按照 lambda 編程的思想編寫，由一個簡單的布爾表達式 <code>(n &amp; 0x1) == 0</code> 組成。</p><ul><li><code>collect</code> 函數將偶數值收集到引用為 <code>evens</code> 的列表中。如下例所示，<code>collect</code> 函數是線程安全的，因此，即使在多個線程之間共享了過濾操作，該函數也可以正常工作。</li></ul><h3 id="方便的功能和輕鬆實現多線程" tabindex="-1">方便的功能和輕鬆實現多線程 <a class="header-anchor" href="#方便的功能和輕鬆實現多線程" aria-label="Permalink to “方便的功能和輕鬆實現多線程”">​</a></h3><p>在生產環境中，數據流的源可能是文件或網絡連接。為了學習流 API, Java 提供了諸如 <code>IntStream</code> 這樣的類型，它可以用各種類型的元素生成流。這裏有一個 <code>IntStream</code> 的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntStream                          // 整型流</span></span>
<span class="line"><span>    .range(1, 2048)                // 生成此範圍內的整型流</span></span>
<span class="line"><span>    .parallel()                    // 為多個線程分區數據</span></span>
<span class="line"><span>    .filter(i -&gt; ((i &amp; 0x1) &gt; 0))  // 奇偶校驗 - 只允許奇數通過</span></span>
<span class="line"><span>    .forEach(System.out::println); // 打印每個值</span></span></code></pre></div><p><code>IntStream</code> 類型包括一個 <code>range</code> 函數，該函數在指定的範圍內生成一個整數值流，在本例中，以 1 為增量，從 1 遞增到 2048。<code>parallel</code> 函數自動劃分該工作到多個線程中，在各個線程中進行過濾和打印。（線程數通常與主機系統上的 CPU 數量匹配。）函數 <code>forEach</code> 參數是一個<em>方法引用</em>，在本例中是對封裝在 <code>System.out</code> 中的 <code>println</code> 方法的引用，方法輸出類型為 <code>PrintStream</code>。方法和構造器引用的語法將在稍後討論。</p><p>由於具有多線程，因此整數值整體上以任意順序打印，但在給定線程中是按順序打印的。例如，如果線程 T1 打印 409 和 411，那麼 T1 將按照順序 409-411 打印，但是其它某個線程可能會預先打印 2045。<code>parallel</code> 調用後面的線程是併發執行的，因此它們的輸出順序是不確定的。</p><h3 id="map-reduce-模式" tabindex="-1">map/reduce 模式 <a class="header-anchor" href="#map-reduce-模式" aria-label="Permalink to “map/reduce 模式”">​</a></h3><p><em>map/reduce</em> 模式在處理大型數據集方面變得很流行。一個 map/reduce 宏操作由兩個微操作構成。首先，將數據分散（<ruby>映射<rt>mapped</rt></ruby>）到各個工作程序中，然後將單獨的結果收集在一起 —— 也可能收集統計起來成為一個值，即<ruby>歸約<rt>reduction</rt></ruby>。歸約可以採用不同的形式，如以下示例所示。</p><p>下面 <code>Number</code> 類的實例用 <code>EVEN</code> 或 <code>ODD</code> 表示有奇偶校驗的整數值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Number {</span></span>
<span class="line"><span>    enum Parity { EVEN, ODD }</span></span>
<span class="line"><span>    private int value;</span></span>
<span class="line"><span>    public Number(int n) { setValue(n); }</span></span>
<span class="line"><span>    public void setValue(int value) { this.value = value; }</span></span>
<span class="line"><span>    public int getValue() { return this.value; }</span></span>
<span class="line"><span>    public Parity getParity() {</span></span>
<span class="line"><span>        return ((value &amp; 0x1) == 0) ? Parity.EVEN : Parity.ODD;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    public void dump() {</span></span>
<span class="line"><span>        System.out.format(&quot;Value: %2d (parity: %s)\\n&quot;, getValue(),</span></span>
<span class="line"><span>                          (getParity() == Parity.ODD ? &quot;odd&quot; : &quot;even&quot;));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下面的代碼演示了用 <code>Number</code> 流進行 map/reduce 的情形，從而表明流 API 不僅可以處理 <code>int</code> 和 <code>float</code> 等基本類型，還可以處理程序員自定義的類類型。</p><p>在下面的代碼段中，使用了 <code>parallelStream</code> 而不是 <code>stream</code> 函數對隨機整數值列表進行流化處理。與前面介紹的 <code>parallel</code> 函數一樣，<code>parallelStream</code> 變體也可以自動執行多線程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>final int howMany = 200;</span></span>
<span class="line"><span>Random r = new Random();</span></span>
<span class="line"><span>Number[] nums = new Number[howMany];</span></span>
<span class="line"><span>for (int i = 0; i &lt; howMany; i++) nums[i] = new Number(r.nextInt(100));</span></span>
<span class="line"><span>List&lt;Number&gt; listOfNums = Arrays.asList(nums);  // 將數組轉化為 list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Integer sum4All = listOfNums</span></span>
<span class="line"><span>    .parallelStream()           // 自動執行多線程</span></span>
<span class="line"><span>    .mapToInt(Number::getValue) // 使用方法引用，而不是 lambda</span></span>
<span class="line"><span>    .sum();                     // 將流值計算出和值</span></span>
<span class="line"><span>System.out.println(&quot;The sum of the randomly generated values is: &quot; + sum4All);</span></span></code></pre></div><p>高階的 <code>mapToInt</code> 函數可以接受一個 lambda 作為參數，但在本例中，它接受一個方法引用，即 <code>Number::getValue</code>。<code>getValue</code> 方法不需要參數，它返回給定的 <code>Number</code> 實例的 <code>int</code> 值。語法並不複雜：類名 <code>Number</code> 後跟一個雙冒號和方法名。回想一下先前的例子 <code>System.out::println</code>，它在 <code>System</code> 類中的 <code>static</code> 屬性 <code>out</code> 後面有一個雙冒號。</p><p>方法引用 <code>Number::getValue</code> 可以用下面的 lambda 表達式替換。參數 <code>n</code> 是流中的 <code>Number</code> 實例中的之一：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mapToInt(n -&gt; n.getValue())</span></span></code></pre></div><p>通常，lambda 表達式和方法引用是可互換的：如果像 <code>mapToInt</code> 這樣的高階函數可以採用一種形式作為參數，那麼這個函數也可以採用另一種形式。這兩個函數式編程結構具有相同的目的 —— 對作為參數傳入的數據執行一些自定義操作。在兩者之間進行選擇通常是為了方便。例如，lambda 可以在沒有封裝類的情況下編寫，而方法則不能。我的習慣是使用 lambda，除非已經有了適當的封裝方法。</p><p>當前示例末尾的 <code>sum</code> 函數通過結合來自 <code>parallelStream</code> 線程的部分和，以線程安全的方式進行歸約。但是，程序員有責任確保在 <code>parallelStream</code> 調用引發的多線程過程中，程序員自己的函數調用（在本例中為 <code>getValue</code>）是線程安全的。</p><p>最後一點值得強調。lambda 語法鼓勵編寫<ruby>純函數<rt>pure function</rt></ruby>，即函數的返回值僅取決於傳入的參數（如果有）；純函數沒有副作用，例如更新一個類中的 <code>static</code> 字段。因此，純函數是線程安全的，並且如果傳遞給高階函數的函數參數（例如 <code>filter</code> 和 <code>map</code> ）是純函數，則流 API 效果最佳。</p><p>對於更細粒度的控制，有另一個流 API 函數，名為 <code>reduce</code>，可用於對 <code>Number</code> 流中的值求和:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Integer sum4AllHarder = listOfNums</span></span>
<span class="line"><span>    .parallelStream()                           // 多線程</span></span>
<span class="line"><span>    .map(Number::getValue)                      // 每個 Number 的值</span></span>
<span class="line"><span>    .reduce(0, (sofar, next) -&gt; sofar + next);  // 求和</span></span></code></pre></div><p>此版本的 <code>reduce</code> 函數帶有兩個參數，第二個參數是一個函數：</p><ul><li>第一個參數（在這種情況下為零）是<em>特徵</em>值，該值用作求和操作的初始值，並且在求和過程中流結束時用作默認值。</li><li>第二個參數是<em>累加器</em>，在本例中，這個 lambda 表達式有兩個參數：第一個參數（<code>sofar</code>）是正在運行的和，第二個參數（<code>next</code>）是來自流的下一個值。運行的和以及下一個值相加，然後更新累加器。請記住，由於開始時調用了 <code>parallelStream</code>，因此 <code>map</code> 和 <code>reduce</code> 函數現在都在多線程上下文中執行。</li></ul><p>在到目前為止的示例中，流值被收集，然後被規約，但是，通常情況下，流 API 中的 <code>Collectors</code> 可以累積值，而不需要將它們規約到單個值。正如下一個代碼段所示，收集活動可以生成任意豐富的數據結構。該示例使用與前面示例相同的 <code>listOfNums</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Map&lt;Number.Parity, List&lt;Number&gt;&gt; numMap = listOfNums</span></span>
<span class="line"><span>    .parallelStream()</span></span>
<span class="line"><span>    .collect(Collectors.groupingBy(Number::getParity));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>List&lt;Number&gt; evens = numMap.get(Number.Parity.EVEN);</span></span>
<span class="line"><span>List&lt;Number&gt; odds = numMap.get(Number.Parity.ODD);</span></span></code></pre></div><p>第一行中的 <code>numMap</code> 指的是一個 <code>Map</code>，它的鍵是一個 <code>Number</code> 奇偶校驗位（<code>ODD</code> 或 <code>EVEN</code>），其值是一個具有指定奇偶校驗位值的 <code>Number</code> 實例的 <code>List</code>。同樣，通過 <code>parallelStream</code> 調用進行多線程處理，然後 <code>collect</code> 調用（以線程安全的方式）將部分結果組裝到 <code>numMap</code> 引用的 <code>Map</code> 中。然後，在 <code>numMap</code> 上調用 <code>get</code> 方法兩次，一次獲取 <code>evens</code>，第二次獲取 <code>odds</code>。</p><p>實用函數 <code>dumpList</code> 再次使用來自流 API 的高階 <code>forEach</code> 函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>private void dumpList(String msg, List&lt;Number&gt; list) {</span></span>
<span class="line"><span>    System.out.println(&quot;\\n&quot; + msg);</span></span>
<span class="line"><span>    list.stream().forEach(n -&gt; n.dump()); // 或者使用 forEach(Number::dump)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是示例運行中程序輸出的一部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The sum of the randomly generated values is: 3322</span></span>
<span class="line"><span>The sum again, using a different method:     3322</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Evens:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Value: 72 (parity: even)</span></span>
<span class="line"><span>Value: 54 (parity: even)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Value: 92 (parity: even)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Odds:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Value: 35 (parity: odd)</span></span>
<span class="line"><span>Value: 37 (parity: odd)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Value: 41 (parity: odd)</span></span></code></pre></div><h3 id="用於代碼簡化的函數式結構" tabindex="-1">用於代碼簡化的函數式結構 <a class="header-anchor" href="#用於代碼簡化的函數式結構" aria-label="Permalink to “用於代碼簡化的函數式結構”">​</a></h3><p>函數式結構（如方法引用和 lambda 表達式）非常適合在流 API 中使用。這些構造代表了 Java 中對高階函數的主要簡化。即使在糟糕的過去，Java 也通過 <code>Method</code> 和 <code>Constructor</code> 類型在技術上支持高階函數，這些類型的實例可以作為參數傳遞給其它函數。由於其複雜性，這些類型在生產級 Java 中很少使用。例如，調用 <code>Method</code> 需要對象引用（如果方法是非<strong>靜態</strong>的）或至少一個類標識符（如果方法是<strong>靜態</strong>的）。然後，被調用的 <code>Method</code> 的參數作為<strong>對象</strong>實例傳遞給它，如果沒有發生多態（那會出現另一種複雜性！），則可能需要顯式向下轉換。相比之下，lambda 和方法引用很容易作為參數傳遞給其它函數。</p><p>但是，新的函數式結構在流 API 之外具有其它用途。考慮一個 Java GUI 程序，該程序帶有一個供用户按下的按鈕，例如，按下以獲取當前時間。按鈕按下的事件處理程序可能編寫如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>JButton updateCurrentTime = new JButton(&quot;Update current time&quot;);</span></span>
<span class="line"><span>updateCurrentTime.addActionListener(new ActionListener() {</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public void actionPerformed(ActionEvent e) {</span></span>
<span class="line"><span>        currentTime.setText(new Date().toString());</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>這個簡短的代碼段很難解釋。關注第二行，其中方法 <code>addActionListener</code> 的參數開始如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>new ActionListener() {</span></span></code></pre></div><p>這似乎是錯誤的，因為 <code>ActionListener</code> 是一個<strong>抽象</strong>接口，而<strong>抽象</strong>類型不能通過調用 <code>new</code> 實例化。但是，事實證明，還有其它一些實例被實例化了：一個實現此接口的未命名內部類。如果上面的代碼封裝在名為 <code>OldJava</code> 的類中，則該未命名的內部類將被編譯為 <code>OldJava$1.class</code>。<code>actionPerformed</code> 方法在這個未命名的內部類中被重寫。</p><p>現在考慮使用新的函數式結構進行這個令人耳目一新的更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>updateCurrentTime.addActionListener(e -&gt; currentTime.setText(new Date().toString()));</span></span></code></pre></div><p>lambda 表達式中的參數 <code>e</code> 是一個 <code>ActionEvent</code> 實例，而 lambda 的主體是對按鈕上的 <code>setText</code> 的簡單調用。</p><h3 id="函數式接口和函數組合" tabindex="-1">函數式接口和函數組合 <a class="header-anchor" href="#函數式接口和函數組合" aria-label="Permalink to “函數式接口和函數組合”">​</a></h3><p>到目前為止，使用的 lambda 已經寫好了。但是，為了方便起見，我們可以像引用封裝方法一樣引用 lambda 表達式。以下一系列簡短示例説明了這一點。</p><p>考慮以下接口定義：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@FunctionalInterface // 可選，通常省略</span></span>
<span class="line"><span>interface BinaryIntOp {</span></span>
<span class="line"><span>    abstract int compute(int arg1, int arg2); // abstract 聲明可以被刪除</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>註釋 <code>@FunctionalInterface</code> 適用於聲明<em>唯一</em>抽象方法的任何接口；在本例中，這個抽象接口是 <code>compute</code>。一些標準接口，（例如具有唯一聲明方法 <code>run</code> 的 <code>Runnable</code> 接口）同樣符合這個要求。在此示例中，<code>compute</code> 是已聲明的方法。該接口可用作引用聲明中的目標類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BinaryIntOp div = (arg1, arg2) -&gt; arg1 / arg2;</span></span>
<span class="line"><span>div.compute(12, 3); // 4</span></span></code></pre></div><p>包 <code>java.util.function</code> 提供各種函數式接口。以下是一些示例。</p><p>下面的代碼段介紹了參數化的 <code>Predicate</code> 函數式接口。在此示例中，帶有參數 <code>String</code> 的 <code>Predicate&lt;String&gt;</code> 類型可以引用具有 <code>String</code> 參數的 lambda 表達式或諸如 <code>isEmpty</code> 之類的 <code>String</code> 方法。通常情況下，Predicate 是一個返回布爾值的函數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Predicate&lt;String&gt; pred = String::isEmpty; // String 方法的 predicate 聲明</span></span>
<span class="line"><span>String[] strings = {&quot;one&quot;, &quot;two&quot;, &quot;&quot;, &quot;three&quot;, &quot;four&quot;};</span></span>
<span class="line"><span>Arrays.asList(strings)</span></span>
<span class="line"><span>   .stream()</span></span>
<span class="line"><span>   .filter(pred)                  // 過濾掉非空字符串</span></span>
<span class="line"><span>   .forEach(System.out::println); // 只打印空字符串</span></span></code></pre></div><p>在字符串長度為零的情況下，<code>isEmpty</code> Predicate 判定結果為 <code>true</code>。 因此，只有空字符串才能進入管道的 <code>forEach</code> 階段。</p><p>下一段代碼將演示如何將簡單的 lambda 或方法引用組合成更豐富的 lambda 或方法引用。考慮這一系列對 <code>IntUnaryOperator</code> 類型的引用的賦值，它接受一個整型參數並返回一個整型值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntUnaryOperator doubled = n -&gt; n * 2;</span></span>
<span class="line"><span>IntUnaryOperator tripled = n -&gt; n * 3;</span></span>
<span class="line"><span>IntUnaryOperator squared = n -&gt; n * n;</span></span></code></pre></div><p><code>IntUnaryOperator</code> 是一個 <code>FunctionalInterface</code>，其唯一聲明的方法為 <code>applyAsInt</code>。現在可以單獨使用或以各種組合形式使用這三個引用 <code>doubled</code>、<code>tripled</code> 和 <code>squared</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int arg = 5;</span></span>
<span class="line"><span>doubled.applyAsInt(arg); // 10</span></span>
<span class="line"><span>tripled.applyAsInt(arg); // 15</span></span>
<span class="line"><span>squared.applyAsInt(arg); // 25</span></span></code></pre></div><p>以下是一些函數組合的樣例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int arg = 5;</span></span>
<span class="line"><span>doubled.compose(squared).applyAsInt(arg); // 5 求 2 次方後乘 2：50</span></span>
<span class="line"><span>tripled.compose(doubled).applyAsInt(arg); // 5 乘 2 後再乘 3：30</span></span>
<span class="line"><span>doubled.andThen(squared).applyAsInt(arg); // 5 乘 2 後求 2 次方：100</span></span>
<span class="line"><span>squared.andThen(tripled).applyAsInt(arg); // 5 求 2 次方後乘 3：75</span></span></code></pre></div><p>函數組合可以直接使用 lambda 表達式實現，但是引用使代碼更簡潔。</p><h3 id="構造器引用" tabindex="-1">構造器引用 <a class="header-anchor" href="#構造器引用" aria-label="Permalink to “構造器引用”">​</a></h3><p>構造器引用是另一種函數式編程構造，而這些引用在比 lambda 和方法引用更微妙的上下文中非常有用。再一次重申，代碼示例似乎是最好的解釋方式。</p>`,76)),t("p",null,[a[1]||(a[1]=s("考慮這個 ",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Plain_old_Java_object"},{default:i(()=>[...a[0]||(a[0]=[s("POJO",-1)])]),_:1}),a[2]||(a[2]=s(" 類：",-1))]),a[19]||(a[19]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class BedRocker { // 基岩的居民</span></span>
<span class="line"><span>    private String name;</span></span>
<span class="line"><span>    public BedRocker(String name) { this.name = name; }</span></span>
<span class="line"><span>    public String getName() { return this.name; }</span></span>
<span class="line"><span>    public void dump() { System.out.println(getName()); }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>該類只有一個構造函數，它需要一個 <code>String</code> 參數。給定一個名字數組，目標是生成一個 <code>BedRocker</code> 元素數組，每個名字代表一個元素。下面是使用了函數式結構的代碼段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>String[] names = {&quot;Fred&quot;, &quot;Wilma&quot;, &quot;Peebles&quot;, &quot;Dino&quot;, &quot;Baby Puss&quot;};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Stream&lt;BedRocker&gt; bedrockers = Arrays.asList(names).stream().map(BedRocker::new);</span></span>
<span class="line"><span>BedRocker[] arrayBR = bedrockers.toArray(BedRocker[]::new);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arrays.asList(arrayBR).stream().forEach(BedRocker::dump);</span></span></code></pre></div><p>在較高的層次上，這個代碼段將名字轉換為 <code>BedRocker</code> 數組元素。具體來説，代碼如下所示。<code>Stream</code> 接口（在包 <code>java.util.stream</code> 中）可以被參數化，而在本例中，生成了一個名為 <code>bedrockers</code> 的 <code>BedRocker</code> 流。</p><p><code>Arrays.asList</code> 實用程序再次用於流化一個數組 <code>names</code>，然後將流的每一項傳遞給 <code>map</code> 函數，該函數的參數現在是構造器引用 <code>BedRocker::new</code>。這個構造器引用通過在每次調用時生成和初始化一個 <code>BedRocker</code> 實例來充當一個對象工廠。在第二行執行之後，名為 <code>bedrockers</code> 的流由五項 <code>BedRocker</code> 組成。</p><p>這個例子可以通過關注高階 <code>map</code> 函數來進一步闡明。在通常情況下，一個映射將一個類型的值（例如，一個 <code>int</code>）轉換為另一個<em>相同</em>類型的值（例如，一個整數的後繼）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>map(n -&gt; n + 1) // 將 n 映射到其後繼</span></span></code></pre></div><p>然而，在 <code>BedRocker</code> 這個例子中，轉換更加戲劇化，因為一個類型的值（代表一個名字的 <code>String</code>）被映射到一個<em>不同</em>類型的值，在這個例子中，就是一個 <code>BedRocker</code> 實例，這個字符串就是它的名字。轉換是通過一個構造器調用來完成的，它是由構造器引用來實現的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>map(BedRocker::new) // 將 String 映射到 BedRocker</span></span></code></pre></div><p>傳遞給構造器的值是 <code>names</code> 數組中的其中一項。</p><p>此代碼示例的第二行還演示了一個你目前已經非常熟悉的轉換：先將數組先轉換成 <code>List</code>，然後再轉換成 <code>Stream</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Stream&lt;BedRocker&gt; bedrockers = Arrays.asList(names).stream().map(BedRocker::new);</span></span></code></pre></div><p>第三行則是另一種方式 —— 流 <code>bedrockers</code> 通過使用<em>數組</em>構造器引用 <code>BedRocker[]::new</code> 調用 <code>toArray</code> 方法:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BedRocker[ ] arrayBR = bedrockers.toArray(BedRocker[]::new);</span></span></code></pre></div><p>該構造器引用不會創建單個 <code>BedRocker</code> 實例，而是創建這些實例的整個數組：該構造器引用現在為 <code>BedRocker[]:new</code>，而不是 <code>BedRocker::new</code>。為了進行確認，將 <code>arrayBR</code> 轉換為 <code>List</code>，再次對其進行流式處理，以便可以使用 <code>forEach</code> 來打印 <code>BedRocker</code> 的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fred</span></span>
<span class="line"><span>Wilma</span></span>
<span class="line"><span>Peebles</span></span>
<span class="line"><span>Dino</span></span>
<span class="line"><span>Baby Puss</span></span></code></pre></div><p>該示例對數據結構的微妙轉換僅用幾行代碼即可完成，從而突出了可以將 lambda，方法引用或構造器引用作為參數的各種高階函數的功能。</p><h3 id="柯里化currying" tabindex="-1"><ruby>柯里化<rt>Currying</rt></ruby> <a class="header-anchor" href="#柯里化currying" aria-label="Permalink to “柯里化Currying”">​</a></h3><p><em>柯里化</em>函數是指減少函數執行任何工作所需的顯式參數的數量（通常減少到一個）。（該術語是為了紀念邏輯學家 Haskell Curry。）一般來説，函數的參數越少，調用起來就越容易，也更健壯。（回想一下一些需要半打左右參數的噩夢般的函數！）因此，應將柯里化視為簡化函數調用的一種嘗試。<code>java.util.function</code> 包中的接口類型適合於柯里化，如以下示例所示。</p><p>引用的 <code>IntBinaryOperator</code> 接口類型是為函數接受兩個整型參數，並返回一個整型值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntBinaryOperator mult2 = (n1, n2) -&gt; n1 * n2;</span></span>
<span class="line"><span>mult2.applyAsInt(10, 20); // 200</span></span>
<span class="line"><span>mult2.applyAsInt(10, 30); // 300</span></span></code></pre></div><p>引用 <code>mult2</code> 強調了需要兩個顯式參數，在本例中是 10 和 20。</p><p>前面介紹的 <code>IntUnaryOperator</code> 比 <code>IntBinaryOperator</code> 簡單，因為前者只需要一個參數，而後者則需要兩個參數。兩者均返回整數值。因此，目標是將名為 <code>mult2</code> 的兩個參數 <code>IntBinraryOperator</code> 柯里化成一個單一的 <code>IntUnaryOperator</code> 版本 <code>curriedMult2</code>。</p><p>考慮 <code>IntFunction&lt;R&gt;</code> 類型。此類型的函數採用整型參數，並返回類型為 <code>R</code> 的結果，該結果可以是另一個函數 —— 更準確地説，是 <code>IntBinaryOperator</code>。讓一個 lambda 返回另一個 lambda 很簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arg1 -&gt; (arg2 -&gt; arg1 * arg2) // 括號可以省略</span></span></code></pre></div><p>完整的 lambda 以 <code>arg1</code> 開頭，而該 lambda 的主體以及返回的值是另一個以 <code>arg2</code> 開頭的 lambda。返回的 lambda 僅接受一個參數（<code>arg2</code>），但返回了兩個數字的乘積（<code>arg1</code> 和 <code>arg2</code>）。下面的概述，再加上代碼，應該可以更好地進行説明。</p><p>以下是如何柯里化 <code>mult2</code> 的概述：</p><ul><li>類型為 <code>IntFunction&lt;IntUnaryOperator&gt;</code> 的 lambda 被寫入並調用，其整型值為 10。返回的 <code>IntUnaryOperator</code> 緩存了值 10，因此變成了已柯里化版本的 <code>mult2</code>，在本例中為 <code>curriedMult2</code>。</li><li>然後使用單個顯式參數（例如，20）調用 <code>curriedMult2</code> 函數，該參數與緩存的參數（在本例中為 10）相乘以生成返回的乘積。。</li></ul><p>這是代碼的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 創建一個接受一個參數 n1 並返回一個單參數 n2 -&gt; n1 * n2 的函數，該函數返回一個（n1 * n2 乘積的）整型數。</span></span>
<span class="line"><span>IntFunction&lt;IntUnaryOperator&gt; curriedMult2Maker = n1 -&gt; (n2 -&gt; n1 * n2);</span></span></code></pre></div><p>調用 <code>curriedMult2Maker</code> 生成所需的 <code>IntUnaryOperator</code> 函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 使用 curriedMult2Maker 獲取已柯里化版本的 mult2。</span></span>
<span class="line"><span>// 參數 10 是上面的 lambda 的 n1。</span></span>
<span class="line"><span>IntUnaryOperator curriedMult2 = curriedMult2Maker2.apply(10);</span></span></code></pre></div><p>值 <code>10</code> 現在緩存在 <code>curriedMult2</code> 函數中，以便 <code>curriedMult2</code> 調用中的顯式整型參數乘以 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curriedMult2.applyAsInt(20); // 200 = 10 * 20</span></span>
<span class="line"><span>curriedMult2.applyAsInt(80); // 800 = 10 * 80</span></span></code></pre></div><p>緩存的值可以隨意更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curriedMult2 = curriedMult2Maker.apply(50); // 緩存 50</span></span>
<span class="line"><span>curriedMult2.applyAsInt(101);               // 5050 = 101 * 50</span></span></code></pre></div><p>當然，可以通過這種方式創建多個已柯里化版本的 <code>mult2</code>，每個版本都有一個 <code>IntUnaryOperator</code>。</p><p>柯里化充分利用了 lambda 的強大功能：可以很容易地編寫 lambda 表達式來返回需要的任何類型的值，包括另一個 lambda。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Java 仍然是基於類的面向對象的編程語言。但是，藉助流 API 及其支持的函數式構造，Java 向函數式語言（例如 Lisp）邁出了決定性的（同時也是受歡迎的）一步。結果是 Java 更適合處理現代編程中常見的海量數據流。在函數式方向上的這一步還使以在前面的代碼示例中突出顯示的管道的方式編寫清晰簡潔的 Java 代碼更加容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dataStream</span></span>
<span class="line"><span>   .parallelStream() // 多線程以提高效率</span></span>
<span class="line"><span>   .filter(...)      // 階段 1</span></span>
<span class="line"><span>   .map(...)         // 階段 2</span></span>
<span class="line"><span>   .filter(...)      // 階段 3</span></span>
<span class="line"><span>   ...</span></span>
<span class="line"><span>   .collect(...);    // 或者，也可以進行歸約：階段 N</span></span></code></pre></div><p>自動多線程，以 <code>parallel</code> 和 <code>parallelStream</code> 調用為例，建立在 Java 的 fork/join 框架上，該框架支持 <ruby>任務竊取<rt>task stealing</rt></ruby> 以提高效率。假設 <code>parallelStream</code> 調用後面的線程池由八個線程組成，並且 <code>dataStream</code> 被八種方式分區。某個線程（例如，T1）可能比另一個線程（例如，T7）工作更快，這意味着應該將 T7 的某些任務移到 T1 的工作隊列中。這會在運行時自動發生。</p><p>在這個簡單的多線程世界中，程序員的主要職責是編寫線程安全函數，這些函數作為參數傳遞給在流 API 中佔主導地位的高階函數。尤其是 lambda 鼓勵編寫純函數（因此是線程安全的）函數。</p><hr>`,44)),t("p",null,[a[4]||(a[4]=s("via: ",-1)),n(e,{href:"https://opensource.com/article/20/1/javastream"},{default:i(()=>[...a[3]||(a[3]=[s("https://opensource.com/article/20/1/javastream",-1)])]),_:1})]),t("p",null,[a[9]||(a[9]=s("作者：",-1)),n(e,{href:"https://opensource.com/users/mkalindepauledu"},{default:i(()=>[...a[5]||(a[5]=[s("Marty Kalin",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),n(e,{href:"https://github.com/laingke"},{default:i(()=>[...a[7]||(a[7]=[s("laingke",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[15]||(a[15]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const C=l(r,[["render",g]]);export{v as __pageData,C as default};
